import React, { useState } from 'react';
import Header from './componentes/Header/Header';
import ListaProductos from './componentes/ListaProductos/ListaProductos';
import CarritoCompras from './componentes/CarritoCompras/CarritoCompras';
import Footer from './componentes/Footer/Footer';
import './App.css';

function App() {
  const [carrito, setCarrito] = useState([]);
  const [mostrarCarrito, setMostrarCarrito] = useState(false);

  const agregarAlCarrito = (producto) => {
    // Verificar si el producto ya está en el carrito
    const productoExistente = carrito.find(item => item.id === producto.id);

    if (productoExistente) {
      // Si ya existe, aumentar la cantidad
      setCarrito(carrito.map(item => 
        item.id === producto.id 
          ? { ...item, cantidad: item.cantidad + 1 } 
          : item
      ));
    } else {
      // Si no existe, agregarlo con cantidad 1
      setCarrito([...carrito, { ...producto, cantidad: 1 }]);
    }
  };

  const eliminarDelCarrito = (id) => {
    setCarrito(carrito.filter(item => item.id !== id));
  };

  const toggleCarrito = () => {
    setMostrarCarrito(!mostrarCarrito);
  };

  return (
    <div className="App">
      <Header cantidadProductos={carrito.reduce((total, item) => total + item.cantidad, 0)} 
              toggleCarrito={toggleCarrito} />

      <main className="contenido-principal">
        {mostrarCarrito ? (
          <CarritoCompras 
            productos={carrito} 
            eliminarDelCarrito={eliminarDelCarrito} 
          />
        ) : (
          <ListaProductos agregarAlCarrito={agregarAlCarrito} />
        )}
      </main>

      <Footer />
    </div>
  );
}

export default App;
